import pandas as pd

def load_data(file_path):
    """
    Load data from a CSV file.

    Args:
    file_path (str): The path to the CSV file.

    Returns:
    pd.DataFrame: The loaded data, or None if loading fails.
    """
    try:
        return pd.read_csv(file_path)
    except Exception as e:
        print(f"Failed to load data: {e}")
        return None

def find_max_accel_stats_z_p99(data):
    """
    Find the timestamp of the highest accel_stats_z_p99.

    Args:
    data (pd.DataFrame): The data to search.

    Returns:
    pd.Timestamp: The timestamp of the highest accel_stats_z_p99, or None if not found.
    """
    if 'accel_stats_z_p99' in data.columns and 'timestamp' in data.columns:
        max_accel_stats_z_p99 = data['accel_stats_z_p99'].max()
        if not pd.isnull(max_accel_stats_z_p99):
            max_row = data.loc[data['accel_stats_z_p99'] == max_accel_stats_z_p99]
            if not max_row.empty:
                return max_row['timestamp'].iloc[0]
    return None

def main():
    file_path = 'path_to_your_data.csv'  # Replace with your data file path
    data = load_data(file_path)
    if data is not None:
        timestamp = find_max_accel_stats_z_p99(data)
        if timestamp is not None:
            print(f"The highest accel_stats_z_p99 was recorded at: {timestamp}")
        else:
            print("Failed to find the maximum accel_stats_z_p99 or its timestamp.")
    else:
        print("Failed to load the data.")

if __name__ == "__main__":
    main()

